function parseIsoDateId(raw) {
  const match = String(raw || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return null;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (!year || !month || !day) return null;
  return { year, month, day };
}

function formatIsoDateId(date) {
  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  const day = String(date.getUTCDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function shiftIsoDateId(dateId, deltaDays) {
  const parsed = parseIsoDateId(dateId);
  const base = parsed
    ? new Date(Date.UTC(parsed.year, parsed.month - 1, parsed.day))
    : new Date();
  base.setUTCDate(base.getUTCDate() + Number(deltaDays || 0));
  return formatIsoDateId(base);
}

function getParisDateIdClient(date = new Date()) {
  try {
    const parts = new Intl.DateTimeFormat("en-CA", {
      timeZone: "Europe/Paris",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).formatToParts(date);
    const year = parts.find((part) => part.type === "year")?.value || "";
    const month = parts.find((part) => part.type === "month")?.value || "";
    const day = parts.find((part) => part.type === "day")?.value || "";
    if (year && month && day) return `${year}-${month}-${day}`;
  } catch (_) {}
  return formatIsoDateId(date);
}

function getVaultWordOfDaySeenStorageKey(audienceKey, dateId) {
  const safeAudience = String(audienceKey || "").trim();
  const safeDateId = String(dateId || "").trim();
  if (!safeAudience || !safeDateId) return "";
  return `${VAULT_WORD_OF_DAY_SEEN_STORAGE_PREFIX}:${safeAudience}:${safeDateId}`;
}

function pickVaultWordOfDayCandidates(words, limit = VAULT_WORD_OF_DAY_MAX_DEFINITION_ATTEMPTS) {
  const seen = new Set();
  const entries = [];
  for (const entry of Array.isArray(words) ? words : []) {
    const word = String(entry?.word || "").trim();
    const key = String(entry?.wordKey || normalizeWord(word)).trim();
    if (!word || !key || seen.has(key)) continue;
    seen.add(key);
    entries.push({ word, wordKey: key });
  }
  for (let i = entries.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [entries[i], entries[j]] = [entries[j], entries[i]];
  }
  return entries.slice(0, Math.max(1, Number(limit) || 1));
}

function buildFakeDailyHistoryDays(todayDateId) {
  if (!ENABLE_FAKE_DAILY_HISTORY) return [];
  const seeds = [0, 1, 2];
  const redNames = ["Atlas", "Nora", "Silo", "Iris", "Milo", "Romy"];
  const blueNames = ["Lena", "Axel", "Maya", "Noe", "Sami", "Loup"];
  return seeds.map((seed, seedIdx) => {
    const redEntries = redNames.map((nick, idx) => ({
      installId: `fake-red-${seedIdx}-${idx}`,
      nick: `${nick}${seedIdx + 1}`,
      score: 1200 - seed * 70 - idx * 55,
      wordsCount: 24 - idx,
      team: "red",
      playerKey: `fake-red-${seedIdx}-${idx}`,
      isPalier: false,
    }));
    const blueEntries = blueNames.map((nick, idx) => ({
      installId: `fake-blue-${seedIdx}-${idx}`,
      nick: `${nick}${seedIdx + 1}`,
      score: 1160 - seed * 65 - idx * 52,
      wordsCount: 23 - idx,
      team: "blue",
      playerKey: `fake-blue-${seedIdx}-${idx}`,
      isPalier: false,
    }));
    const entries = [...redEntries, ...blueEntries].sort((a, b) => {
      const diff = (Number(b?.score) || 0) - (Number(a?.score) || 0);
      if (diff !== 0) return diff;
      return String(a?.nick || "").localeCompare(String(b?.nick || ""));
    });
    const redBalanced = redEntries.reduce((sum, entry) => sum + (Number(entry.score) || 0), 0);
    const blueBalanced = blueEntries.reduce((sum, entry) => sum + (Number(entry.score) || 0), 0);
    return {
      // Keep test pages distinct from real history dates so they always remain visible in test mode.
      dateId: `TEST-${shiftIsoDateId(todayDateId || null, -(seedIdx + 1))}`,
      totalPlayers: entries.length,
      entries,
      battle: {
        totalsRawByTeam: { red: redBalanced, blue: blueBalanced },
        totalsBalancedByTeam: { red: redBalanced, blue: blueBalanced },
        winnerTeam: redBalanced === blueBalanced ? null : redBalanced > blueBalanced ? "red" : "blue",
      },
      isFake: true,
    };
  });
}

function splitUrlPathAndSuffix(src) {
  const raw = String(src || "").trim();
  if (!raw) return { path: "", suffix: "" };
  const queryIdx = raw.indexOf("?");
  const hashIdx = raw.indexOf("#");
  let cut = raw.length;
  if (queryIdx >= 0) cut = Math.min(cut, queryIdx);
  if (hashIdx >= 0) cut = Math.min(cut, hashIdx);
  return {
    path: raw.slice(0, cut),
    suffix: raw.slice(cut),
  };
}

function stripExtension(src) {
  const { path, suffix } = splitUrlPathAndSuffix(src);
  if (!path) return String(src || "");
  return `${path.replace(/\.[a-z0-9]{2,5}$/i, "")}${suffix}`;
}

function buildCandidatesFromBase(base, order) {
  const cleaned = stripExtension(base);
  const { path: cleanPath, suffix } = splitUrlPathAndSuffix(cleaned);
  if (!cleanPath) return [];
  return order.map((ext) => `${cleanPath}.${ext}${suffix}`);
}

function buildImageCandidates(url) {
  const candidates = buildCandidatesFromBase(url, ["webp", "png"]);
  return candidates.length ? candidates : [url];
}

function buildImageManifest(items) {
  return (Array.isArray(items) ? items : []).map((item) => ({
    key: item.key,
    type: "image",
    candidates: buildImageCandidates(item.url),
    priority: item.priority,
  }));
}

function makeFileKey(url) {
  return `file_${String(url || "")
    .replace(/^\//, "")
    .replace(/[^a-z0-9]+/gi, "_")
    .toLowerCase()}`;
}

function buildFileManifest(items) {
  return (Array.isArray(items) ? items : []).map((url) => ({
    key: makeFileKey(url),
    type: "file",
    candidates: [url],
    priority: "low",
  }));
}

function dedupeManifest(entries) {
  const map = new Map();
  (Array.isArray(entries) ? entries : []).forEach((entry) => {
    if (!entry?.key) return;
    map.set(entry.key, entry);
  });
  return Array.from(map.values());
}

const BOOT_ASSET_MANIFEST_BASE = dedupeManifest([
  ...ASSET_MANIFEST_BASE.filter((entry) => entry?.type !== "sfx"),
  ...buildImageManifest(BOOT_ASSET_IMAGES),
  ...buildFileManifest(BOOT_ASSET_FILES),
]);

const DEFINITION_PLACEHOLDER_RE = /^[.\u2026\u00b7\s-]+$/;

function sanitizeDefinitionText(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  if (DEFINITION_PLACEHOLDER_RE.test(text)) return "";
  return text;
}

function pickDefinitionText(data) {
  if (!data) return "";
  const primary = sanitizeDefinitionText(data.definition);
  if (primary) return primary;
  return sanitizeDefinitionText(data.extract);
}

function buildDefinitionFallbacks(clean, data, tried) {
  const out = [];
  const push = (value) => {
    const term = String(value || "").trim();
    if (!term) return;
    const key = normalizeWord(term);
    if (!key || tried.has(key)) return;
    tried.add(key);
    out.push(term);
  };
  push(data?.lemma);
  push(data?.title);
  push(data?.matchedTitle);
  const normalized = normalizeWord(clean);
  if (normalized && !tried.has(normalized)) {
    tried.add(normalized);
    out.push(normalized);
  }
  return out;
}

function getGridSizeForRoom(roomKey) {
  return ROOM_OPTIONS[roomKey]?.gridSize || 4;
}

function getViewportSize() {
  if (typeof window === "undefined") return { width: 0, height: 0 };
  const width = Math.round(
    window.innerWidth ||
      (typeof document !== "undefined" ? document.documentElement?.clientWidth : 0) ||
      0
  );
  const height = Math.round(
    window.innerHeight ||
      (typeof document !== "undefined" ? document.documentElement?.clientHeight : 0) ||
      0
  );
  return { width, height };
}

function hasCoarsePointer() {
  if (typeof window === "undefined" || !window.matchMedia) return false;
  return (
    window.matchMedia("(pointer: coarse)").matches ||
    window.matchMedia("(hover: none)").matches
  );
}

function hasFinePointer() {
  if (typeof window === "undefined" || !window.matchMedia) return false;
  return (
    window.matchMedia("(pointer: fine)").matches ||
    window.matchMedia("(any-pointer: fine)").matches
  );
}

function computeIsMobileLayout() {
  if (typeof window === "undefined") return false;
  const { width, height } = getViewportSize();
  const minDim = Math.min(width, height);
  const isNarrow = width <= MOBILE_LAYOUT_MAX_WIDTH;
  const isTouch =
    hasCoarsePointer() ||
    "ontouchstart" in window ||
    (typeof navigator !== "undefined" && navigator.maxTouchPoints > 0);
  const isHybridDesktop = hasFinePointer() && width >= 900;
  const isTouchCompact = isTouch && !isHybridDesktop && minDim <= TOUCH_LAYOUT_MAX_MIN_DIM;
  return isNarrow || isTouchCompact;
}

function computeIsUltraCompact() {
  if (typeof window === "undefined") return false;
  const { width, height } = getViewportSize();
  const minDim = Math.min(width, height);
  const maxDim = Math.max(width, height);
  const aspect = minDim > 0 ? maxDim / minDim : 0;
  const isTouch =
    hasCoarsePointer() ||
    "ontouchstart" in window ||
    (typeof navigator !== "undefined" && navigator.maxTouchPoints > 0);
  const isHybridDesktop = hasFinePointer() && width >= 900;
  return (
    isTouch &&
    !isHybridDesktop &&
    minDim <= ULTRA_COMPACT_MAX_MIN_DIM &&
    aspect > 0 &&
    aspect <= 1.35
  );
}

function isStandaloneDisplayMode() {
  if (typeof window === "undefined") return false;
  return (
    window.matchMedia?.("(display-mode: standalone)")?.matches ||
    window.matchMedia?.("(display-mode: fullscreen)")?.matches ||
    window.navigator?.standalone === true
  );
}

function isAppleMobileUserAgent(ua) {
  return /iPhone|iPad|iPod/i.test(String(ua || ""));
}

function computeIsIosStandalone() {
  if (typeof navigator === "undefined") return false;
  return isAppleMobileUserAgent(navigator.userAgent || "") && isStandaloneDisplayMode();
}

function computeIsAndroidWebBrowser() {
  if (typeof window === "undefined" || typeof navigator === "undefined") return false;
  const ua = navigator.userAgent || "";
  const isAndroid = /Android/i.test(ua);
  if (!isAndroid) return false;
  return !isStandaloneDisplayMode();
}

function isAndroidWebViewUserAgent(ua) {
  const value = String(ua || "");
  if (!/Android/i.test(value)) return false;
  if (/; wv\)/i.test(value) || /\bwv\b/i.test(value)) return true;
  const hasVersionChrome = /Version\/[\d.]+\s+Chrome\/[\d.]+/i.test(value);
  const hasMobileSafari = /Mobile Safari\/[\d.]+/i.test(value);
  const looksBrowser = /(SamsungBrowser|CriOS|FxiOS|EdgA|OPR|YaBrowser|DuckDuckGo|UCBrowser)/i.test(value);
  return hasVersionChrome && hasMobileSafari && !looksBrowser;
}

function isLikelySamsungDeviceUserAgent(ua) {
  const value = String(ua || "");
  return /SM-[A-Z0-9]+/i.test(value) || /SAMSUNG/i.test(value);
}

function isFirefoxMobileUserAgent(ua) {
  const value = String(ua || "");
  if (!/(Firefox|FxiOS)/i.test(value)) return false;
  return /Android|iPhone|iPad|iPod|Mobile/i.test(value);
}

function getDefaultRoomId() {
  if (typeof window !== "undefined") {
    const isMobile = computeIsMobileLayout();
    return isMobile ? "room-4x4" : "room-4x4";
  }
  return "room-4x4";
}

function clampValue(value, min, max) {
  if (!Number.isFinite(value)) return min;
  return Math.min(Math.max(value, min), max);
}

function normalizeDesktopColumnFractions(rawFractions, defaultFractions = DESKTOP_COLUMN_DEFAULT_FRACTIONS) {
  const safeDefaults =
    Array.isArray(defaultFractions) && defaultFractions.length > 0
      ? defaultFractions
      : DESKTOP_COLUMN_DEFAULT_FRACTIONS;
  const source = Array.isArray(rawFractions) ? rawFractions : safeDefaults;
  const safe = safeDefaults.map((fallback, idx) => {
    const value = Number(source[idx]);
    if (!Number.isFinite(value) || value <= 0) return fallback;
    return value;
  });
  const sum = safe.reduce((acc, value) => acc + value, 0);
  if (!Number.isFinite(sum) || sum <= 0) {
    return [...safeDefaults];
  }
  return safe.map((value) => value / sum);
}

function areDesktopFractionsEqual(a, b, epsilon = 0.0005) {
  if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false;
  for (let i = 0; i < a.length; i += 1) {
    if (Math.abs((Number(a[i]) || 0) - (Number(b[i]) || 0)) > epsilon) return false;
  }
  return true;
}

function normalizeDesktopColumnOrder(rawOrder, defs = LIVE_DESKTOP_COLUMN_DEFS) {
  const safeDefs = Array.isArray(defs) && defs.length ? defs : LIVE_DESKTOP_COLUMN_DEFS;
  const allowed = safeDefs.map((entry) => String(entry?.id || "").trim()).filter(Boolean);
  const requested = Array.isArray(rawOrder) ? rawOrder : [];
  const seen = new Set();
  const next = [];
  for (const rawId of requested) {
    const id = String(rawId || "").trim();
    if (!id || seen.has(id) || !allowed.includes(id)) continue;
    seen.add(id);
    next.push(id);
  }
  for (const id of allowed) {
    if (seen.has(id)) continue;
    next.push(id);
  }
  return next;
}

function readDesktopColumnOrderForInstall(installId, storageScope, defs) {
  if (typeof window === "undefined" || typeof localStorage === "undefined") {
    return normalizeDesktopColumnOrder(null, defs);
  }
  const key = String(installId || "").trim();
  const scope = String(storageScope || "live").trim() || "live";
  if (!key) return normalizeDesktopColumnOrder(null, defs);
  try {
    const raw = localStorage.getItem(`${DESKTOP_COLUMN_ORDER_STORAGE_PREFIX}:${scope}:${key}`);
    if (!raw) return normalizeDesktopColumnOrder(null, defs);
    const parsed = JSON.parse(raw);
    return normalizeDesktopColumnOrder(parsed, defs);
  } catch (_) {
    return normalizeDesktopColumnOrder(null, defs);
  }
}

function writeDesktopColumnOrderForInstall(installId, storageScope, order, defs) {
  if (typeof localStorage === "undefined") return;
  const key = String(installId || "").trim();
  const scope = String(storageScope || "live").trim() || "live";
  if (!key) return;
  try {
    localStorage.setItem(
      `${DESKTOP_COLUMN_ORDER_STORAGE_PREFIX}:${scope}:${key}`,
      JSON.stringify(normalizeDesktopColumnOrder(order, defs))
    );
  } catch (_) {}
}

function readDesktopColumnFractionsForInstall(installId, storageScope, defaultFractions) {
  if (typeof window === "undefined" || typeof localStorage === "undefined") {
    return normalizeDesktopColumnFractions(defaultFractions, defaultFractions);
  }
  const key = String(installId || "").trim();
  const scope = String(storageScope || "live").trim() || "live";
  if (!key) return normalizeDesktopColumnFractions(defaultFractions, defaultFractions);
  try {
    const raw = localStorage.getItem(`${DESKTOP_COLUMN_RESIZE_STORAGE_PREFIX}:${scope}:${key}`);
    if (!raw) return normalizeDesktopColumnFractions(defaultFractions, defaultFractions);
    const parsed = JSON.parse(raw);
    return normalizeDesktopColumnFractions(parsed, defaultFractions);
  } catch (_) {
    return normalizeDesktopColumnFractions(defaultFractions, defaultFractions);
  }
}

function writeDesktopColumnFractionsForInstall(installId, storageScope, fractions, defaultFractions) {
  if (typeof localStorage === "undefined") return;
  const key = String(installId || "").trim();
  const scope = String(storageScope || "live").trim() || "live";
  if (!key) return;
  try {
    localStorage.setItem(
      `${DESKTOP_COLUMN_RESIZE_STORAGE_PREFIX}:${scope}:${key}`,
      JSON.stringify(normalizeDesktopColumnFractions(fractions, defaultFractions))
    );
  } catch (_) {}
}

function getChatDrawerOrientationKey() {
  if (typeof window === "undefined") return "portrait";
  const width = Number(window.innerWidth) || 0;
  const height = Number(window.innerHeight) || 0;
  return width > height ? "landscape" : "portrait";
}

function readStoredChatDrawerCalibration() {
  if (typeof window === "undefined" || typeof localStorage === "undefined") {
    return null;
  }
  try {
    const raw = localStorage.getItem(CHAT_DRAWER_DEVICE_CALIBRATION_STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    const ratio = Number(parsed?.ratio);
    const heightPx = Number(parsed?.heightPx);
    const orientation = String(parsed?.orientation || "").trim() || "portrait";
    if (!Number.isFinite(ratio) || ratio <= 0) return null;
    if (!Number.isFinite(heightPx) || heightPx <= 0) return null;
    return {
      ratio: clampValue(ratio, CHAT_DRAWER_CALIBRATION_MIN_RATIO, CHAT_DRAWER_CALIBRATION_MAX_RATIO),
      heightPx: Math.max(1, Math.round(heightPx)),
      orientation,
    };
  } catch (_) {
    return null;
  }
}

function writeStoredChatDrawerCalibration(calibration) {
  if (typeof localStorage === "undefined") return;
  const ratio = Number(calibration?.ratio);
  const heightPx = Number(calibration?.heightPx);
  const orientation = String(calibration?.orientation || "").trim() || "portrait";
  if (!Number.isFinite(ratio) || ratio <= 0) return;
  if (!Number.isFinite(heightPx) || heightPx <= 0) return;
  try {
    localStorage.setItem(
      CHAT_DRAWER_DEVICE_CALIBRATION_STORAGE_KEY,
      JSON.stringify({
        ratio: clampValue(ratio, CHAT_DRAWER_CALIBRATION_MIN_RATIO, CHAT_DRAWER_CALIBRATION_MAX_RATIO),
        heightPx: Math.max(1, Math.round(heightPx)),
        orientation,
        updatedAt: Date.now(),
      })
    );
  } catch (_) {}
}

function buildRankingSignature(list) {
  if (!Array.isArray(list) || list.length === 0) return "";
  const size = list.length;
  const limit = Math.min(size, 20);
  let out = `n:${size}|`;
  for (let i = 0; i < limit; i += 1) {
    const entry = list[i] || {};
    const nick = String(entry.nick || "").trim();
    const userId = Number.isInteger(Number(entry.userId)) ? Number(entry.userId) : "";
    const score =
      Number.isFinite(entry.score) ? entry.score : Number.isFinite(entry.points) ? entry.points : 0;
    const rank = Number.isFinite(entry.rank) ? entry.rank : i + 1;
    const gobbles = Number.isFinite(entry.gobbles) ? entry.gobbles : 0;
    const dailyChampion = entry.isDailyChampion || entry.crowned || entry.isWeeklyChampion ? "1" : "0";
    const weeklyVocabChampion = entry.isWeeklyVocabChampion ? "1" : "0";
    out += `${nick}:${userId}:${rank}:${score}:${gobbles}:${dailyChampion}:${weeklyVocabChampion}|`;
  }
  return out;
}

function buildPlayersSignature(list) {
  if (!Array.isArray(list) || list.length === 0) return "";
  const size = list.length;
  const limit = Math.min(size, 24);
  let out = `n:${size}|`;
  for (let i = 0; i < limit; i += 1) {
    const entry = list[i] || {};
    const nick = String(entry.nick || "").trim();
    const userId = Number.isInteger(Number(entry.userId)) ? Number(entry.userId) : "";
    const team = String(entry.team || "");
    const bot = entry.isBot ? "1" : "0";
    const dailyChampion = entry.isDailyChampion || entry.crowned || entry.isWeeklyChampion ? "1" : "0";
    const weeklyVocabChampion = entry.isWeeklyVocabChampion ? "1" : "0";
    out += `${nick}:${userId}:${team}:${bot}:${dailyChampion}:${weeklyVocabChampion}|`;
  }
  return out;
}

function normalizeRotationTurns(turns) {
  if (!Number.isFinite(turns)) return 0;
  const mod = turns % 4;
  return mod < 0 ? mod + 4 : mod;
}

function rotateIndexByTurns(index, size, turns) {
  if (!Number.isInteger(index) || !Number.isInteger(size) || size <= 0) {
    return index;
  }
  const t = normalizeRotationTurns(turns);
  if (t === 0) return index;
  const row = Math.floor(index / size);
  const col = index % size;
  if (t === 1) return col * size + (size - 1 - row);
  if (t === 2) return (size - 1 - row) * size + (size - 1 - col);
  return (size - 1 - col) * size + row;
}

function mapDisplayToBoardIndex(displayIndex, size, turns) {
  const t = normalizeRotationTurns(turns);
  return rotateIndexByTurns(displayIndex, size, (4 - t) % 4);
}

function normalizeBonusLabel(bonus) {
  if (bonus === "W2") return "M2";
  if (bonus === "W3") return "M3";
  return bonus;
}

function createDailySpecialPlacements() {
  return { L2: null, L3: null, M2: null, M3: null };
}

function createDailyWordSlots() {
  return Array.from({ length: DAILY_SPECIAL_WORD_TARGET }, (_, idx) => ({
    id: idx,
    word: "",
    display: "",
    path: [],
  }));
}

function getDailySpecialWordStartTile(path) {
  const first = Array.isArray(path) ? Number(path[0]) : NaN;
  return Number.isInteger(first) && first >= 0 ? first : null;
}

function getDailySpecialWordBlockedReason(word, path, slots, targetSlot) {
  const normalized = normalizeWord(String(word || ""));
  if (!normalized || normalized.length < 2) return "";
  const startTile = getDailySpecialWordStartTile(path);
  if (startTile == null) return "";
  const list = Array.isArray(slots) ? slots : [];
  const hasSameStartTile = list.some(
    (slot, idx) =>
      idx !== targetSlot && getDailySpecialWordStartTile(slot?.path) === startTile
  );
  return hasSameStartTile ? "Première tuile déjà utilisée" : "";
}

function stripBoardBonuses(board) {
  if (!Array.isArray(board)) return [];
  return board.map((cell) => ({
    ...(cell || {}),
    bonus: null,
  }));
}

function applyDailySpecialPlacements(board, placements) {
  const base = stripBoardBonuses(board);
  const occupied = new Set();
  DAILY_SPECIAL_BONUSES.forEach((bonus) => {
    const rawPlacement = placements?.[bonus];
    const idx = Number.isInteger(rawPlacement) ? rawPlacement : null;
    if (!Number.isInteger(idx) || idx < 0 || idx >= base.length) return;
    if (occupied.has(idx) || !base[idx]) return;
    occupied.add(idx);
    base[idx] = { ...base[idx], bonus };
  });
  return base;
}

function getEffectiveDailySpecialPlacements(basePlacements, dragState, boardLength) {
  const next = {
    ...(basePlacements && typeof basePlacements === "object" ? basePlacements : {}),
  };
  if (!dragState || typeof dragState !== "object") return next;
  const bonusKey = typeof dragState.bonusKey === "string" ? dragState.bonusKey : "";
  if (!bonusKey) return next;
  const hoverIndex = Number.isInteger(dragState.hoverIndex) ? dragState.hoverIndex : null;
  next[bonusKey] = null;
  const canPlaceOnGrid =
    Number.isInteger(hoverIndex) &&
    hoverIndex >= 0 &&
    hoverIndex < (Number.isFinite(boardLength) ? boardLength : 0);
  if (!canPlaceOnGrid) return next;
  DAILY_SPECIAL_BONUSES.forEach((otherBonus) => {
    if (otherBonus === bonusKey) return;
    if (Number.isInteger(next?.[otherBonus]) && next[otherBonus] === hoverIndex) {
      next[otherBonus] = null;
    }
  });
  next[bonusKey] = hoverIndex;
  return next;
}

function areStringArraysEqual(a, b) {
  if (a === b) return true;
  if (!Array.isArray(a) || !Array.isArray(b)) return false;
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i += 1) {
    if (a[i] !== b[i]) return false;
  }
  return true;
}

function getBonusBadgeClass(displayBonus) {
  if (displayBonus === "L3") return "bg-blue-700 text-white";
  if (displayBonus === "L2") return "bg-sky-400 text-slate-900";
  if (displayBonus === "M3") return "bg-red-600 text-white";
  if (displayBonus === "M2") return "bg-[#ffbfb4] border border-[#f87171] text-slate-900";
  return "bg-slate-600 text-white";
}

function getBonusLetterRingClass(displayBonus) {
  if (displayBonus === "L3") return "theme-letter-ring theme-letter-ring-L3";
  if (displayBonus === "L2") return "theme-letter-ring theme-letter-ring-L2";
  if (displayBonus === "M3") return "theme-letter-ring theme-letter-ring-M3";
  if (displayBonus === "M2") return "theme-letter-ring theme-letter-ring-M2";
  return "";
}

function normalizeLetterKey(letter) {
  if (!letter) return "";
  if (letter === "Qu") return "qu";
  return String(letter).toLowerCase();
}

function normalizeNickKey(nick) {
  return String(nick || "").trim().toLowerCase();
}

