function pickStableOcidMessage(messages, key) {
  if (!Array.isArray(messages) || !messages.length) return "";
  const raw = String(key || "");
  let hash = 0;
  for (let i = 0; i < raw.length; i += 1) {
    hash = (hash * 31 + raw.charCodeAt(i)) >>> 0;
  }
  return messages[hash % messages.length] || messages[0];
}

function formatOcidMessage(template, values = {}) {
  return String(template || "").replace(/\{(\w+)\}/g, (_, key) =>
    Object.prototype.hasOwnProperty.call(values, key) ? String(values[key]) : ""
  );
}

const TILE_LETTER_SCALE_MIN = 0.8;
const TILE_LETTER_SCALE_MAX = 1.45;
const TILE_LETTER_SCALE_DEFAULT = 1.2;

function normalizeTileLetterScale(value, fallback = TILE_LETTER_SCALE_DEFAULT) {
  const base = Number.isFinite(Number(fallback)) ? Number(fallback) : TILE_LETTER_SCALE_DEFAULT;
  const raw = Number(value);
  if (!Number.isFinite(raw)) {
    return clampValue(base, TILE_LETTER_SCALE_MIN, TILE_LETTER_SCALE_MAX);
  }
  return clampValue(raw, TILE_LETTER_SCALE_MIN, TILE_LETTER_SCALE_MAX);
}

function getThemeCategoryValue(theme, category) {
  if (!theme || typeof theme !== "object") return undefined;
  if (category === "tileColor") return theme.tileColor;
  if (category === "font") return theme.font;
  if (category === "letterScale")
    return normalizeTileLetterScale(theme.letterScale, TILE_LETTER_SCALE_DEFAULT);
  if (category === "letterColor") return theme.letterColor;
  if (category === "background") return theme.background;
  if (category === "material") return theme.material;
  if (category === "specialIndicator") return theme.specialIndicator;
  if (category === "uiContrast") return theme.uiContrast;
  if (category === "darkMode") return !!theme.darkMode;
  return undefined;
}

function getTileMaterialClass(materialPreset) {
  if (materialPreset === "native") return "";
  if (materialPreset === "bubble") return "theme-material-bubble";
  if (materialPreset === "rounded-square") return "theme-material-rounded-square";
  if (materialPreset === "square") return "theme-material-square";
  return "theme-material-classic";
}

function getTileColorTextureStyle(index, size, tileColorPreset) {
  const tileColorMeta = TILE_COLOR_MAP[tileColorPreset];
  if (!tileColorMeta?.texture) return null;
  const safeSize = Number.isInteger(size) && size > 0 ? size : 4;
  const safeIndex = Number.isInteger(index) && index >= 0 ? index : 0;
  const row = Math.floor(safeIndex / safeSize);
  const col = safeIndex % safeSize;
  const denom = Math.max(1, safeSize - 1);
  const x = (col / denom) * 100;
  const y = (row / denom) * 100;
  return {
    backgroundImage: `url("${tileColorMeta.texture}")`,
    backgroundSize: `${safeSize * 100}% ${safeSize * 100}%`,
    backgroundPosition: `${x}% ${y}%`,
    backgroundRepeat: "no-repeat",
    backgroundBlendMode: "multiply",
  };
}

function getTileColorSwatchStyle(tileColorOption) {
  if (!tileColorOption || typeof tileColorOption !== "object") return {};
  const borderColor = "rgba(0, 0, 0, 0.22)";
  if (tileColorOption.texture) {
    return {
      backgroundColor: tileColorOption.bg || "#ffffff",
      backgroundImage: `url("${tileColorOption.texture}")`,
      backgroundSize: "cover",
      backgroundPosition: "center",
      backgroundRepeat: "no-repeat",
      borderColor,
    };
  }
  return {
    background: tileColorOption.bg || "#ffffff",
    borderColor,
  };
}

function buildCompletedTargetPattern(pattern, word) {
  const cleanWord = String(word || "").trim();
  if (!cleanWord) return pattern || "";
  return cleanWord.toUpperCase();
}

function buildTargetBlankPattern(length) {
  if (!Number.isFinite(length) || length <= 0) return "";
  return Array.from({ length }).map(() => "_").join(" ");
}

function interpolateColorChannel(start, end, ratio) {
  const safeRatio = Math.max(0, Math.min(1, Number(ratio) || 0));
  return Math.round(start + (end - start) * safeRatio);
}

function buildTargetHintEntries(cells, wordIndices) {
  const entries = [];
  const seen = new Set();
  const safeCells = Array.isArray(cells) ? cells : [];
  const safeWordIndices = Array.isArray(wordIndices) ? wordIndices : [];
  for (let i = 0; i < safeCells.length; i += 1) {
    const boardIndex = safeCells[i];
    const wordIndex = safeWordIndices[i];
    if (!Number.isInteger(boardIndex) || boardIndex < 0 || seen.has(boardIndex)) continue;
    seen.add(boardIndex);
    entries.push({
      boardIndex,
      wordIndex: Number.isInteger(wordIndex) && wordIndex >= 0 ? wordIndex : null,
    });
  }
  return entries;
}

function buildTargetHintStyleMap(cells, wordIndices, wordLength) {
  const entries = buildTargetHintEntries(cells, wordIndices);
  if (!entries.length) return new Map();
  const map = new Map();
  const lastWordIndex = Math.max(
    1,
    Number.isFinite(wordLength) && wordLength > 1
      ? Math.trunc(wordLength) - 1
      : entries.reduce((max, entry) => Math.max(max, entry.wordIndex ?? 0), 0)
  );
  for (const entry of entries) {
    const boardIndex = entry.boardIndex;
    const ratio =
      entry.wordIndex == null ? 0 : Math.max(0, Math.min(1, entry.wordIndex / lastWordIndex));
    const red = interpolateColorChannel(6, 92, ratio);
    const green = interpolateColorChannel(116, 214, ratio);
    const blue = interpolateColorChannel(60, 170, ratio);
    const fillAlpha = 0.4 - ratio * 0.16;
    const fillEdgeAlpha = 0.56 - ratio * 0.18;
    const insetAlpha = 0.7 - ratio * 0.2;
    const outlineAlpha = 0.98 - ratio * 0.14;
    const glowAlpha = 0.56 - ratio * 0.18;
    map.set(boardIndex, {
      "--tile-hint-rgb": `${red}, ${green}, ${blue}`,
      "--tile-hint-fill-alpha": fillAlpha.toFixed(3),
      "--tile-hint-fill-edge-alpha": fillEdgeAlpha.toFixed(3),
      "--tile-hint-inset-alpha": insetAlpha.toFixed(3),
      "--tile-hint-outline-alpha": outlineAlpha.toFixed(3),
      "--tile-hint-glow-alpha": glowAlpha.toFixed(3),
    });
  }
  return map;
}

function buildTargetHintOverlayStyleMap(cells, wordIndices, wordLength, variant = "fill") {
  const entries = buildTargetHintEntries(cells, wordIndices);
  if (!entries.length) return new Map();
  const map = new Map();
  const lastWordIndex = Math.max(
    1,
    Number.isFinite(wordLength) && wordLength > 1
      ? Math.trunc(wordLength) - 1
      : entries.reduce((max, entry) => Math.max(max, entry.wordIndex ?? 0), 0)
  );
  for (const entry of entries) {
    const boardIndex = entry.boardIndex;
    const ratio =
      entry.wordIndex == null ? 0 : Math.max(0, Math.min(1, entry.wordIndex / lastWordIndex));
    const red = interpolateColorChannel(8, 118, ratio);
    const green = interpolateColorChannel(126, 228, ratio);
    const blue = interpolateColorChannel(64, 176, ratio);
    const strongAlpha = 0.76 - ratio * 0.34;
    const midAlpha = 0.44 - ratio * 0.18;
    const glowAlpha = 0.56 - ratio * 0.18;
    const style =
      variant === "outline"
        ? {
            background:
              `linear-gradient(135deg, rgba(${red}, ${green}, ${blue}, ${strongAlpha * 0.42}) 0%, ` +
              `rgba(${red}, ${green}, ${blue}, ${midAlpha * 0.2}) 58%, rgba(255, 255, 255, 0.12) 100%)`,
            boxShadow:
              `inset 0 0 0 3px rgba(${red}, ${green}, ${blue}, ${0.98 - ratio * 0.12}), ` +
              `0 0 16px 3px rgba(${red}, ${green}, ${blue}, ${glowAlpha})`,
          }
        : {
            background:
              `linear-gradient(135deg, rgba(${red}, ${green}, ${blue}, ${strongAlpha}) 0%, ` +
              `rgba(${red}, ${green}, ${blue}, ${midAlpha}) 50%, rgba(255, 255, 255, 0.22) 100%)`,
            boxShadow:
              `0 0 0 3px rgba(${red}, ${green}, ${blue}, ${0.5 - ratio * 0.12}), ` +
              `inset 0 0 0 2px rgba(${red}, ${green}, ${blue}, ${0.78 - ratio * 0.18}), ` +
              `inset 0 10px 16px rgba(255, 255, 255, ${0.16 - ratio * 0.05})`,
          };
    map.set(boardIndex, style);
  }
  return map;
}

function isSystemAuthor(rawAuthor) {
  if (!rawAuthor) return false;
  const simplified = String(rawAuthor)
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
  return simplified === "system" || simplified === "systeme";
}

function isSystemChatMessage(message) {
  if (!message || typeof message !== "object") return false;
  if (message.type === "system" || message.channel === "system") return true;
  return isSystemAuthor(message.author || message.nick || "");
}

function formatChatUnreadSuffix(unreadCount) {
  const value = Number(unreadCount) || 0;
  if (value <= 0) return "";
  if (value >= 10) return " (9+)";
  return ` (${value})`;
}

const CHAT_TIME_FORMATTER = new Intl.DateTimeFormat("fr-FR", {
  hour: "2-digit",
  minute: "2-digit",
});

function formatChatMessageTime(message) {
  const ts = getChatMessageSortTime(message);
  if (!Number.isFinite(ts) || ts <= 0) return "";
  try {
    return CHAT_TIME_FORMATTER.format(new Date(ts));
  } catch (_) {
    return "";
  }
}

function isEditedChatMessage(message) {
  const editedAt = Number(message?.editedAt);
  return Number.isFinite(editedAt) && editedAt > 0;
}

