function patchChatMessageById(messages, updatedMessage) {
  const normalized = normalizeChatMessageShape(updatedMessage);
  if (!normalized?.id) return messages;
  let changed = false;
  const next = (Array.isArray(messages) ? messages : []).map((entry) => {
    if (!entry || entry.id !== normalized.id) return entry;
    changed = true;
    return {
      ...entry,
      ...normalized,
    };
  });
  return changed ? next : messages;
}

function removeChatMessageById(messages, messageId) {
  const targetId = typeof messageId === "string" ? messageId.trim() : "";
  if (!targetId) return messages;
  const list = Array.isArray(messages) ? messages : [];
  const next = list.filter((entry) => entry?.id !== targetId);
  return next.length === list.length ? messages : next;
}

function patchChatMessageReactions(messages, patch) {
  const messageId = typeof patch?.messageId === "string" ? patch.messageId.trim() : "";
  if (!messageId) return messages;
  const normalizedReactions = normalizeChatReactions(patch?.reactions);
  let changed = false;
  const next = (Array.isArray(messages) ? messages : []).map((entry) => {
    if (!entry || entry.id !== messageId) return entry;
    changed = true;
    const updated = { ...entry };
    if (Object.keys(normalizedReactions).length) updated.reactions = normalizedReactions;
    else delete updated.reactions;
    if (patch?.updatedAt) {
      const ts = Number(patch.updatedAt);
      if (Number.isFinite(ts) && ts > 0) {
        updated.reactionsUpdatedAt = ts;
      }
    }
    return updated;
  });
  return changed ? next : messages;
}

function findNewReactionFromOthers(prevMessage, patchReactions, selfInstallId) {
  if (!prevMessage || typeof prevMessage !== "object") return null;
  const previousReactions = normalizeChatReactions(prevMessage.reactions);
  const nextReactions = normalizeChatReactions(patchReactions);
  const selfId = typeof selfInstallId === "string" ? selfInstallId.trim() : "";
  for (const [emoji, users] of Object.entries(nextReactions)) {
    const previousUsers = new Set(
      (Array.isArray(previousReactions[emoji]) ? previousReactions[emoji] : [])
        .map((user) => (typeof user?.installId === "string" ? user.installId.trim() : ""))
        .filter(Boolean)
    );
    const addedByOtherUser = (Array.isArray(users) ? users : []).find((user) => {
      const userInstallId =
        typeof user?.installId === "string" ? user.installId.trim() : "";
      if (!userInstallId || previousUsers.has(userInstallId)) return false;
      return !selfId || userInstallId !== selfId;
    });
    if (addedByOtherUser) {
      const nick =
        typeof addedByOtherUser?.nick === "string" ? addedByOtherUser.nick.trim() : "";
      return {
        emoji,
        actorNick: nick || "Quelqu'un",
      };
    }
  }
  return null;
}

function intersectViewportRects(a, b) {
  if (!a || !b) return null;
  const left = Math.max(Number(a.left) || 0, Number(b.left) || 0);
  const top = Math.max(Number(a.top) || 0, Number(b.top) || 0);
  const right = Math.min(Number(a.right) || 0, Number(b.right) || 0);
  const bottom = Math.min(Number(a.bottom) || 0, Number(b.bottom) || 0);
  if (!(right > left && bottom > top)) return null;
  return {
    left,
    top,
    right,
    bottom,
    width: right - left,
    height: bottom - top,
  };
}

function getVisibleChatElementRect(element) {
  if (typeof window === "undefined" || !(element instanceof HTMLElement)) return null;
  const rawRect = element.getBoundingClientRect();
  if (!(rawRect.width > 0 && rawRect.height > 0)) return null;
  const style = window.getComputedStyle(element);
  if (
    style.display === "none" ||
    style.visibility === "hidden" ||
    Number(style.opacity || "1") === 0
  ) {
    return null;
  }
  let clipRect = {
    left: 0,
    top: 0,
    right: window.innerWidth || 0,
    bottom: window.innerHeight || 0,
  };
  let current = element;
  while (current && current instanceof HTMLElement) {
    const currentStyle = window.getComputedStyle(current);
    const overflowValue = `${currentStyle.overflow} ${currentStyle.overflowX} ${currentStyle.overflowY}`;
    if (/(auto|scroll|hidden|clip)/.test(overflowValue)) {
      clipRect = intersectViewportRects(clipRect, current.getBoundingClientRect());
      if (!clipRect) return null;
    }
    current = current.parentElement;
  }
  return intersectViewportRects(rawRect, clipRect);
}

function findVisibleChatMessageToastOrigin(messageId) {
  if (typeof document === "undefined") return null;
  const safeMessageId = typeof messageId === "string" ? messageId.trim() : "";
  if (!safeMessageId) return null;
  const candidates = Array.from(document.querySelectorAll("[data-chat-message-id]")).filter(
    (node) => node instanceof HTMLElement && node.dataset.chatMessageId === safeMessageId
  );
  let bestRect = null;
  let bestArea = 0;
  for (const element of candidates) {
    const visibleRect = getVisibleChatElementRect(element);
    if (!visibleRect) continue;
    const area = visibleRect.width * visibleRect.height;
    if (area <= bestArea) continue;
    bestArea = area;
    bestRect = visibleRect;
  }
  if (!bestRect) return null;
  return {
    kind: "message",
    x: Math.round(bestRect.left + bestRect.width / 2),
    y: Math.round(bestRect.bottom - Math.min(12, bestRect.height * 0.35)),
  };
}

function findChatLauncherToastOrigin() {
  if (typeof document === "undefined") return null;
  const launcher = document.querySelector("[data-chat-launcher-button='true']");
  if (!(launcher instanceof HTMLElement)) return null;
  const visibleRect = getVisibleChatElementRect(launcher);
  if (!visibleRect) return null;
  return {
    kind: "launcher",
    x: Math.round(visibleRect.left + visibleRect.width / 2),
    y: Math.round(visibleRect.top + visibleRect.height / 2),
  };
}

function buildBottomChatToastOrigin() {
  if (typeof window === "undefined") {
    return { kind: "bottom", x: 160, y: 580 };
  }
  return {
    kind: "bottom",
    x: Math.round((window.innerWidth || 320) / 2),
    y: Math.round((window.innerHeight || 640) - 28),
  };
}

function getChatMessageSortTime(message) {
  const tsCandidate =
    message?.t ??
    message?.ts ??
    message?.timestamp ??
    message?.createdAt ??
    0;
  const ts = Number(tsCandidate);
  return Number.isFinite(ts) ? ts : 0;
}

function dedupeChatMessages(messages) {
  const seen = new Set();
  const out = [];
  for (const raw of Array.isArray(messages) ? messages : []) {
    const normalized = normalizeChatMessageShape(raw);
    if (!normalized) continue;
    const id = typeof normalized.id === "string" ? normalized.id : "";
    const key = id
      ? `id:${id}`
      : `fallback:${getChatMessageSortTime(normalized)}:${normalized.nick || normalized.author || ""}:${normalized.text || ""}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(normalized);
  }
  return out;
}

function capChatMessagesByType(messages) {
  const deduped = dedupeChatMessages(messages);
  const system = [];
  const user = [];
  for (let i = deduped.length - 1; i >= 0; i -= 1) {
    const msg = deduped[i];
    if (isSystemChatMessage(msg)) {
      if (system.length < CHAT_SYSTEM_HISTORY_MAX) {
        system.push(msg);
      }
      continue;
    }
    if (user.length < CHAT_MESSAGES_HISTORY_MAX) {
      user.push(msg);
    }
  }
  const merged = [...user.reverse(), ...system.reverse()];
  merged.sort((a, b) => {
    const tA = getChatMessageSortTime(a);
    const tB = getChatMessageSortTime(b);
    if (tA !== tB) return tA - tB;
    return String(a?.id || "").localeCompare(String(b?.id || ""));
  });
  return merged.slice(-CHAT_BUFFER_MAX);
}

function readStoredChatMessages() {
  if (typeof window === "undefined" || typeof localStorage === "undefined") {
    return [];
  }
  try {
    const raw = localStorage.getItem(CHAT_MESSAGES_STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return capChatMessagesByType(parsed);
  } catch (_) {
    return [];
  }
}

function getBroadcastMessageKey(message) {
  if (!message || typeof message !== "object") return "";
  const idPart = typeof message.id === "string" ? message.id.trim() : "";
  const updatedPart =
    typeof message.updatedAt === "string" ? message.updatedAt.trim() : "";
  if (idPart && updatedPart) return `${idPart}:${updatedPart}`.slice(0, 140);
  if (idPart) return idPart.slice(0, 140);
  if (updatedPart) return updatedPart.slice(0, 140);
  return "";
}

function getBroadcastSeenStorageKey(installId, messageKey) {
  const safeInstallId = typeof installId === "string" ? installId.trim() : "";
  const safeMessageKey = typeof messageKey === "string" ? messageKey.trim() : "";
  if (!safeInstallId || !safeMessageKey) return "";
  return `${BROADCAST_SEEN_STORAGE_PREFIX}:${safeInstallId}:${safeMessageKey}`;
}

const formatNumber = (value) =>
  typeof value === "number" ? value.toLocaleString("fr-FR") : null;

